#!/usr/bin/env python3
"""Trace original primary hit, active zero-health actor and post-weapon death."""
import hashlib,json,struct,subprocess
from unicorn import __version__,UC_HOOK_CODE
from unicorn.x86_const import UC_X86_REG_EAX,UC_X86_REG_EDX
from native_ai_audit import Native,ROOT,EXE,RUNNER,f32
fixtures=[dict(player=player,victim=victim,missile=missile,health=health,shielded=shield,dt=f32(1/60)) for player in [0,1] for victim in [0,1] for missile in [False,True] for health in [0,1,5,100] for shield in [False,True]]
native=[]
for f in fixtures:
 n=Native();rows=[RUNNER,RUNNER+0x1000];nodes=[RUNNER+0x8000,RUNNER+0x8100];victim=f['victim'];attacker=1-victim;target=rows[victim];owner=rows[attacker];profiles=[0 if i==f['player'] else 1 for i in range(2)];visible={};sounds=[]
 n.write(0x48f104,'2I',*nodes);n.write(0x48f158,'I',2);n.write(0x518aa8,'f',f['dt']);n.write(0x49064c,'f',f['dt']);n.write(0x490650,'I',1);n.write(0x48f1b4,'B',0);n.write(0x48f160,'B',0);n.write(0x48d8b8,'B',0);n.write(0x4b5d50,'B',0);n.write(0x48d89c,'I',0);n.write(0x48d8a8,'I',0)
 for i in range(8):n.write(0x48d8d8+i*80,'I',2);n.write(0x48d8e0+i*80,'I',0xffffffff);n.write(0x48d8c4+i*80,'II',0,0)
 for i,(address,node,profile) in enumerate(zip(rows,nodes,profiles)):
  n.write(address,'II',i,profile);n.write(address+8,'B',1);n.write(address+0xc,'I',node);n.write(node+0x4c,'I',address);n.write(address+0x14d,'B',1);n.write(address+0x15e,'B',1);n.write(address+0x15c,'B',1);n.write(address+0x1b5,'B',int(i==f['player']));n.write(address+0xd8,'I',1);n.write(address+0x2c,'fff',100+i*30,0,100);n.write(address+0x104,'f',45);n.write(address+0x8c,'fff',f32(-2**-.5),0,f32(-2**-.5));n.write(address+0x498,'I',4);n.write(address+0x4a8,'II',0,1);n.write(address+0x6e0,'I',12);n.write(address+0x6e8,'ff',1,1);n.write(0x48d8d8+profile*80,'I',0 if i==f['player'] else 1);n.write(0x48d8e0+profile*80,'I',i);n.write(0x48d8d0+profile*80,'f',f['health'] if i==victim else 100);n.write(0x48d8e5+profile*80,'B',int(i==victim and f['shielded']))
  for slot in range(12):n.write(address+0x4fc+slot*4,'I',0x600000+i*0x1000+slot*0x20);n.write(address+0x52c+slot*4,'I',0x610000+i*0x1000+slot*0x20)
 n.write(owner+0x6ac,'I',1 if f['missile'] else 4)
 n.cpu.mem_write(0x411ee8,b'\x31\xc0\xc3')
 for address in [0x42f39c,0x42e128,0x42df0c,0x42cc4c,0x44b628,0x44b4f0,0x44b67c,0x45bddc,0x41837c,0x415ac8,0x415a50,0x4182f4,0x419008,0x42ed54,0x468928,0x4161b8,0x418990,0x440294,0x4162fc,0x433928,0x434b94,0x42b0e4]:n.cpu.mem_write(address,b'\xc3')
 for address in [0x45a54c,0x45a6bc,0x468a0c,0x45bec0,0x45be08]:n.cpu.mem_write(address,b'\xc2\x0c\x00')
 n.cpu.mem_write(0x459580,b'\xb8'+struct.pack('<I',RUNNER+0xb000)+b'\xc3');n.cpu.mem_write(0x435d68,b'\x31\xc0\xc2\x04\x00')
 def visibility(cpu,address,size,data):visible[cpu.reg_read(UC_X86_REG_EAX)]=bool(cpu.reg_read(UC_X86_REG_EDX))
 n.cpu.hook_add(UC_HOOK_CODE,visibility,begin=0x44b4f0,end=0x44b4f0);n.cpu.hook_add(UC_HOOK_CODE,lambda cpu,address,size,data:sounds.append(cpu.reg_read(UC_X86_REG_EAX)),begin=0x4182f4,end=0x4182f4)
 def snapshot():return dict(health=n.read(0x48d8d0+profiles[victim]*80,'f')[0],shielded=bool(n.read(0x48d8e5+profiles[victim]*80,'B')[0]),active=bool(n.read(target+0x15e,'B')[0]),kills=n.read(0x48d8c4+profiles[attacker]*80,'I')[0],count=n.read(target+0x494,'I')[0],slots=[dict(slot=i,age=n.read(target+0x4cc+i*4,'f')[0],visible=visible.get(0x610000+victim*0x1000+i*0x20,False)) for i in range(12) if n.read(target+0x4bc+i,'B')[0]],sounds=list(sounds))
 pointer=struct.unpack('<f',struct.pack('<I',owner))[0];n.call(0x435828,[0,0,-1,pointer],eax=0,edx=target);samples=[snapshot()]
 n.call(0x43753c,eax=target);samples.append(snapshot());n.call(0x42f2d0,eax=nodes[victim]);samples.append(snapshot());n.call(0x42f2d0,eax=nodes[victim]);samples.append(snapshot());native.append(samples)
js="""
import {Simulation} from './src/simulation.js';let s='';for await(let x of process.stdin)s+=x;
console.log(JSON.stringify(JSON.parse(s).map(f=>{let sim=new Simulation({player:f.player,ground:()=>0,blocked:()=>false,wallContact:()=>null});sim.countdown=0;sim.ai=()=>({});sim.projectileContact=()=>{};sim.runners.forEach(r=>r.dead=Infinity);let r=sim.runners[f.victim],owner=1-f.victim;Object.assign(r,{dead:0,inactive:false,x:100+f.victim*30,y:0,z:100,yaw:Math.PI/4,speed:0,health:f.health,shield:f.shielded?10:0});sim.events=[];let sounds=[];let emit=sim.emit.bind(sim);sim.emit=(type,data)=>{if(type==='shot')sounds.push(data.soundId);emit(type,data)};const snapshot=()=>({health:r.health,shielded:r.shield>0,active:!r.dead,kills:sim.runners[owner].kills,count:sim.projectiles.filter(p=>p.owner===r.id&&p.life>0).length,slots:sim.projectiles.filter(p=>p.owner===r.id&&p.life>0).map(p=>({slot:p.slot,age:p.age,visible:!p.pending&&!p.hidden})),sounds:[...sounds]});sim.damage(r,f.missile?140:4,owner,f.missile?'Missile':'Laser',{armor:false,power:false});let samples=[snapshot()];sim.fire(r);samples.push(snapshot());sim.step(f.dt);samples.push(snapshot());sim.step(f.dt);samples.push(snapshot());return samples})));
"""
rebuilt=json.loads(subprocess.check_output(['node','--import','./utils/tests/setup.js','--input-type=module','-e',js],input=json.dumps(fixtures).encode(),cwd=ROOT));mismatches=[dict(fixture=i,native=a,rebuild=b) for i,(a,b) in enumerate(zip(native,rebuilt)) if a!=b]
report=dict(scope='Actual original 435828 primary-hit helper with real 418e44 health and 418c0c kill-counter update; then actual victim Fire allocation, 42f2d0 actor/4371d0 weapon action and 43360c health check through real 4336cc/43495c/43781c deactivation and 440674 shield cleanup. Compare health, active flag, kill count, pool state, slot age/visibility and shot sound calls before and after each phase.',sha256=hashlib.sha256(EXE.read_bytes()).hexdigest(),emulator='Unicorn '+__version__,fixtures=fixtures,native=native,rebuild=rebuilt,mismatches=mismatches,passed=not mismatches,limitations=['Controlled primary hit and two actor calls, with supplied profile mapping, shield flags, stationary pose and unit armor/power factors. No complete native collision/scene traversal or multiplayer.','Native physics and camera operations, impact recoil response, scene intersections, render setters, hit score/text delivery, audio playback, wreck/debris creation and post-death HUD are stubs. Visibility/sound calls are captured; original hit recoil can affect projectile velocity, which is outside the compared fields.','Does not compare exact death/respawn callback delay, barrier/Ion/other effect timing, zero-health recharge/escape behavior, or rendered frames.'])
(ROOT/'private/verification/damage-death-native-audit.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(dict(fixtures=len(fixtures),mismatches=len(mismatches),passed=not mismatches),indent=2))
if mismatches:raise SystemExit(1)
